:root {
  --ink: #202744;
  --paper: #fffdf7;
  --lavender: #dcd6ff;
  --muted: #68708e;
}

.ticket {
  width: 460px;
  border: 2px solid var(--ink);
  border-radius: 14px;
  background: var(--paper);
}

.ticket-header {
  display: flex;
  justify-content: space-between;
  padding: 10px 16px;
}

.details {
  padding: 18px 16px;
}

.details h1 {
  margin: 0;
  font-size: 23px;
}

.details p {
  margin: 5px 0 0;
  color: var(--muted);
}

.ticket-footer {
  display: flex;
  justify-content: space-between;
  padding: 9px 16px;
  background: var(--lavender);
}
